} else if (inputTopic.endsWith('/state') && data && typeof data === 'object') {
  for (const key of ['mist','fan','light','mist_state','mode']) {
    if (data[key] !== undefined) snapshot[key] = String(data[key]);
  }
  if (data.water_lockout === true) snapshot.mist_state = 'WATER_LOCKOUT';
} else if (inputTopic.endsWith('/availability')) {
  const availability = typeof data === 'string' ? data : String(data);
  if (availability === 'online' || availability === 'offline') snapshot.availability = availability;
}
flow.set('orchidDashboardSnapshot', snapshot);
const lastTelemetry = flow.get('orchidDashboardTelemetryAt') || 0;
const isStale = lastTelemetry > 0 && Date.now() - lastTelemetry > 15000;
const connection = snapshot.availability === 'offline' ? 'OFFLINE' : isStale ? 'STALE' : snapshot.availability === 'online' ? 'ONLINE' : 'WAITING';
const show = (value, suffix) => value === null ? '—' : `${value}${suffix}`;
const climateHistory = telemetryUpdate ? [
  {topic:'Temperature °C', payload:snapshot.temperature_c},
  {topic:'Humidity %', payload:snapshot.humidity_pct}
].filter(point => Number.isFinite(point.payload)) : null;
